using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading.Tasks;using UnityEngine;using UnityEngine.AI;using FireSafety;
public static class TestCampusNPCs {
public static Task<string> RunExt()=>RunModes(new[]{TrainingMode.FireExtinguisher}); public static Task<string> RunEvac()=>RunModes(new[]{TrainingMode.Evacuation}); public static async Task<string> RunModes(TrainingMode[] modes){Application.runInBackground=true;var s=TrainingSession.Instance;var c=UnityEngine.Object.FindAnyObjectByType<SchoolEvacuationController>();var checks=new List<object>();void Check(string n,bool p,object e=null)=>checks.Add(new{name=n,pass=p,evidence=e});var records=new List<object>();
foreach(var mode in modes){s.MainMenu();s.ChooseMode(mode);Check(mode+" resets occupants and exit",c.people.All(p=>!p.Arrived&&!p.Departed&&Vector3.Distance(p.transform.position,p.initialPosition)<.05f)&&!c.exit.OpenRequested);s.StartSimulation();var previous=c.people.Select(p=>p.transform.position).ToArray();int wallHits=0;bool crossedClosed=false,walked=false;float maxStep=0;double start=Time.realtimeSinceStartupAsDouble;
while(Time.realtimeSinceStartupAsDouble-start<30&&c.ArrivedCount<11){await Task.Delay(100);if(s.Page=="Pause")s.Resume();for(int i=0;i<c.people.Length;i++){var p=c.people[i];var now=p.transform.position;var delta=now-previous[i];maxStep=Mathf.Max(maxStep,delta.magnitude);if(delta.magnitude>.01f){var hits=Physics.SphereCastAll(previous[i]+Vector3.up*.7f,.12f,delta.normalized,delta.magnitude,1,QueryTriggerInteraction.Ignore);wallHits+=hits.Count(h=>!h.collider.GetComponentInParent<DesktopPlayerController>()&&!h.collider.GetComponentInParent<ExitDoor>());if(previous[i].x<6.5f&&now.x>=6.5f&&!c.exit.IsPassable)crossedClosed=true;}previous[i]=now;walked|=p.legacyAnimation.IsPlaying(p.walkClip);}}
Check(mode+" all eleven reach individual assembly positions",c.ArrivedCount==11,new{seconds=Time.realtimeSinceStartupAsDouble-start,arrived=c.ArrivedCount});Check(mode+" agents have valid paths and no wall intersections",wallHits==0&&!crossedClosed&&c.people.All(p=>!p.PathFailed),new{wallHits,crossedClosed});Check(mode+" walked with animation rather than teleporting",walked&&maxStep<1.2f&&c.people.All(p=>p.DistanceTravelled>9),new{walked,maxStep});Check(mode+" NPC arrival does not finish player training",!s.evacuation.Completed&&s.evaluation.Result==null&&s.Playing);Check(mode+" sprinkler policy preserved",mode==TrainingMode.FireExtinguisher?s.simulation.ActiveSprinklers==0:s.simulation.sprinklers.All(w=>w.Available));records.Add(new{mode=mode.ToString(),positions=c.people.Select(p=>new{p.name,pos=p.transform.position.ToString(),p.DistanceTravelled}).ToArray()});
s.Retry();Check(mode+" retry resets every occupant",c.people.All(p=>!p.Arrived&&!p.Departed&&Vector3.Distance(p.transform.position,p.initialPosition)<.05f));s.MainMenu();}
var json=Newtonsoft.Json.JsonConvert.SerializeObject(new{scope="Real-time NavMesh movement in both modes; 100ms swept collision samples at torso height; player remains at spawn",checks,records},Newtonsoft.Json.Formatting.Indented);File.WriteAllText(Path.GetFullPath("../Documentation/CampusNPCRegression-"+modes[0]+".json"),json);return checks.Count+" NPC checks saved";}}


